import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String customerId = req.getParameter("cid");

        // Validate report type against known values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - dates are parameterized but sort column is dynamic
        StringBuilder query = new StringBuilder();
        query.append("SELECT id, customer_name, amount, created_at FROM reports ");
        query.append("WHERE report_type = ? AND created_at BETWEEN ? AND ? ");

        if (customerId != null && !customerId.isEmpty()) {
            // Developer note: cid is always numeric from our frontend dropdown
            query.append("AND customer_id = ").append(customerId).append(" ");
        }

        // Sort column - we check it's alphanumeric but allow underscores
        if (sortCol != null && sortCol.matches("[a-zA-Z_]+")) {
            query.append("ORDER BY ").append(sortCol);
        } else {
            query.append("ORDER BY created_at DESC");
        }

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            stmt.setString(1, reportType);
            stmt.setString(2, startDate);
            stmt.setString(3, endDate);

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            var writer = resp.getWriter();
            writer.write("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) writer.write(",\n");
                writer.write(String.format(
                    "{\"id\":%d,\"name\":\"%s\",\"amount\":%.2f,\"date\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("customer_name").replace("\"", "\\\""),
                    rs.getDouble("amount"),
                    rs.getString("created_at")
                ));
                first = false;
            }
            writer.write("\n]");
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory")
                || type.equals("returns") || type.equals("audit"));
    }

    // Health check endpoint used by ALB target group
    @Override
    protected void doHead(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        resp.setStatus(200);
    }
}
